'use strict';

// MODULES //

import isArrayBuffer from '@stdlib/assert/is-arraybuffer';
import { factory as factory } from './../../../vector/ctor';
import format from '@stdlib/string/format';


// VARIABLES //

var ctor = factory( 'generic' );


// MAIN //

/**
* Returns a "generic" vector (i.e., a one-dimensional ndarray).
*
* @param {(NonNegativeInteger|Collection|Iterable)} [arg] - length, typed array, array-like object, or iterable
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only vector
* @param {string} [options.mode='throw'] - specifies how to handle indices which exceed vector dimensions
* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
* @throws {TypeError} first argument must be either a length, typed array, array-like object, iterable, or options object
* @throws {TypeError} must provide valid options
* @returns {ndarray} one-dimensional ndarray
*
* @example
* import numel from '@stdlib/ndarray/numel';
*
* var arr = new GenericVector();
* // returns <ndarray>
*
* var len = numel( arr );
* // returns 0
*
* @example
* import numel from '@stdlib/ndarray/numel';
*
* var arr = new GenericVector( 2 );
* // returns <ndarray>
*
* var len = numel( arr );
* // returns 2
*
* @example
* import numel from '@stdlib/ndarray/numel';
*
* var arr = new GenericVector( [ 1.0, 2.0 ] );
* // returns <ndarray>
*
* var len = numel( arr );
* // returns 2
*/
function GenericVector() {
	var arg;
	if ( arguments.length === 0 ) {
		return new ctor();
	}
	arg = arguments[ 0 ];
	if ( isArrayBuffer( arg ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be either a length, an array-like object, or an iterable. Value: `%s`.', arg ) );
	}
	if ( arguments.length === 1 ) {
		return new ctor( arg );
	}
	return new ctor( arg, arguments[ 1 ] );
}


// EXPORTS //

export default GenericVector;
